-- 868: India stock prices (502 rows, 90 materials), the INSERT from migration 833 on its own.
-- Migration 833 ran as one transaction; its link step failed on the renamed column, which rolled
-- back this insert too. This file has the insert only. Idempotent (ON CONFLICT DO UPDATE).
-- Link to raw_materials is done by 867.

ON CONFLICT (reference_material, stock_form, location)
DO UPDATE SET price_per_kg = EXCLUDED.price_per_kg, currency_code = EXCLUDED.currency_code, source = EXCLUDED.source, updated_at = now();
